  "pay.method.wallet": "வாலட் மூலம் செலுத்துங்கள்",
  "pay.none_country": "உங்கள் நாட்டில் ஆன்லைன் கட்டணம் இன்னும் கிடைக்கவில்லை. இடத்தில் செலுத்துங்கள்.",
  "gst.title": "இந்திய ஜிஎஸ்டி பில்லிங்",
  "gst.none": "இன்னும் ஜிஎஸ்டி சுயவிவரம் இல்லை. விலைப்பட்டியல்களிலும் ரசீதுகளிலும் CGST, SGST அல்லது IGST காட்ட உங்கள் GSTIN ஐச் சேர்க்கவும்.",
  "gst.add": "ஜிஎஸ்டி சுயவிவரத்தைச் சேர்க்கவும்",
  "gst.edit": "ஜிஎஸ்டி சுயவிவரத்தைத் திருத்தவும்",
