  'aco.pack.hint': 'இந்தத் திரையில் உள்ள அதே பதிவுகளிலிருந்து உருவாக்கப்பட்ட பிராண்டட் PDF திறக்கும்.',
  'aco.src.body': 'பணியாளர் செலவு அங்கீகரிக்கப்பட்ட ஊதியப் பட்டியலிலிருந்தும், இடச் செலவு உறுதி செய்யப்பட்ட இட முன்பதிவுகளிலிருந்தும் எடுக்கப்படுகிறது. ஒரு திட்டத்துக்கு இவை இல்லாதபோது மட்டுமே கைமுறைச் செலவு பதிவுகள் பயன்படுத்தப்படும்.',
  'aco.src.unpriced': '{n} அங்கீகரிக்கப்பட்ட நேரப்பதிவுகளுக்கு ஊதிய விதி இல்லை, எனவே அவற்றின் செலவு கணக்கில் சேர்க்கப்படவில்லை.',
  'aco.src.unbooked': '{n} அமர்வுகளுக்கு இட முன்பதிவு இல்லை, எனவே அவற்றின் இடச் செலவு கணக்கில் சேர்க்கப்படவில்லை.',
  'aco.src.superseded': '{n} கைமுறைப் பதிவுகள் ஒதுக்கி வைக்கப்பட்டன, ஏனெனில் ஊதியப் பட்டியல் அல்லது முன்பதிவு அவற்றை ஏற்கனவே உள்ளடக்குகிறது.',
  'aco.costs.intro': 'இவை P&L-க்கான மேலாண்மைக் கணக்கு வரிகள் (மைதான வாடகை, உபகரணங்கள், மேல்செலவில் ஒரு பங்கு). இவை பணம் செலுத்தல்களோ விலைப்பட்டியல்களோ அல்ல; பணத்தை நகர்த்தாது. பணியாளர் மற்றும் இடச் செலவு அங்கீகரிக்கப்பட்ட ஊதியப் பட்டியல், உறுதி செய்யப்பட்ட முன்பதிவுகளிலிருந்து எடுக்கப்படும்; அவை இல்லாதபோது மட்டும் இங்கே பதிவிடுங்கள். பதிவுகள் திருத்தப்படாது: ரத்து செய்து மீண்டும் சேர்க்கவும்.',
  'aco.fund.unattributed': 'திட்டத்துடன் இணைக்கப்படாத செலவு',
  'aco.fund.unattributed_note': 'திட்டம் இல்லாத அங்கீகரிக்கப்பட்ட ஊதிய சரிசெய்தல்கள் மற்றும் நேரப்பதிவுகள்; மொத்தத்திலிருந்து கழிக்கப்பட்டது, பகிரப்படவில்லை',
  'aco.line.payroll': 'பணியாளர் செலவு · அங்கீகரிக்கப்பட்ட ஊதியப் பட்டியல்',
