  'guide.classes.title': 'வகுப்புகளைக் கண்காணி',
  'guide.tax.title': 'வரியை அமை',
  'guide.revenue.title': 'வருவாயைப் பகிர்',
  'guide.reports.title': 'அறிக்கைகளைப் பார்',
  'guide.create.why': 'மற்ற அனைத்தும் நிறுவனத்தைச் சார்ந்தவை, எனவே இங்கிருந்து தொடங்குங்கள். நீங்கள் அதன் உரிமையாளர் ஆவீர்கள்.',
  'guide.venues.why': 'அமர்வுகள், ஆடுகளங்கள், கட்டணங்கள் அரங்குடன் இணைந்தவை; திட்டமிடும் முன் பயிற்சி இடங்களைச் சேருங்கள்.',
  'guide.staff.why': 'பயிற்சியாளர்கள், வரவேற்பு மற்றும் நிதிக்கு தனித்தனி அணுகல் கொடுங்கள். ஒவ்வொருவரும் தங்கள் பங்குக்குத் தேவையானதை மட்டுமே காண்பர்.',
  'guide.suppliers.why': 'பராமரிப்பு ஒப்பந்ததாரர்கள் மற்றும் உபகரண விநியோகஸ்தர்களை ஓரிடத்தில் வைத்து, அவர்கள் சேவை செய்யும் அரங்குகளுடன் இணைத்து, கோரிக்கைகளை முடியும் வரை கண்காணியுங்கள்.',
  'guide.programmes.why': 'குடும்பங்கள் வாங்குவது திட்டம்: அணி, பருவ வகுப்பு அல்லது முகாம், விலை மற்றும் இடங்களுடன்.',
  'guide.coaches.why': 'பயிற்சியாளர்களை பணியாளர், ஒப்பந்தக்காரர் அல்லது வருவாய்ப் பங்காளராகச் சேர்த்து, விதிமுறைகளை எழுத்தில் ஒப்புக்கொள்ளுங்கள்.',
  'guide.students.why': 'விசாரணையிலிருந்து சேர்க்கை வரை மக்களை நகர்த்துங்கள். குழந்தைகளுக்கு பெற்றோர் அல்லது பாதுகாவலர் ஒப்புதல் அளிப்பர்.',
  'guide.classes.why': 'இன்றையும் வாரத்தையும் ஒரே பார்வையில் காணுங்கள், வருகையைப் பதிவு செய்யுங்கள், ஈடு மற்றும் ரத்து வகுப்புகளைத் தெரியும்படி வையுங்கள்.',
  'guide.tax.why': 'வசூலித்த மற்றும் செலுத்திய வரியை, உங்கள் வரி விதிகள் மற்றும் விலைப்பட்டியலில் வரி விவரங்களுடன் அறியுங்கள்.',
  'guide.revenue.why': 'பயிற்சியாளர்களுடன் பணம் எப்படிப் பகிரப்படும், பொதுச் செலவுகள் திட்டங்களில் எப்படிப் பிரிக்கப்படும் என்பதை முடிவு செய்யுங்கள்.',
  'guide.reports.why': 'நிர்வாக முகப்பில் விளைவுகள், தக்கவைப்பு, நிதி நிலை மற்றும் கூட்டாளிகளைக் காணுங்கள்; தேவையானதை ஏற்றுமதி செய்யுங்கள்.',
