  'ac.locked_sub': 'கல்வி அணுகலுக்கு உரிமையாளர் அல்லது நிர்வாகியிடம் கேளுங்கள். மதிப்பெண்கள் விளையாட்டு வீரரின் ஒப்புதலுடன் மட்டுமே படிக்கப்படும்.',
