  'ac.coach.title': 'உங்கள் வீரர்களின் பள்ளி கடமைகள்',
  'ac.coach.sub': 'நீங்கள் பயிற்றுவிக்கும் வீரர்கள், அவர்களின் முன்னேற்ற நிலை, பள்ளி மோதல் அல்லது வருகை குறிப்புகளைப் பார்க்கலாம். பார்க்க விளையாட்டு வீரர்களைத் திறக்கவும்.',
  'ac.empty.title': 'விளையாட்டையும் படிப்பையும் ஒன்றாக நடத்துங்கள்',
  'ac.empty.body': 'ஒவ்வொரு வீரரையும் அவரது பள்ளியுடன் இணையுங்கள், பிறகு எதைப் பகிர வேண்டும் என்று வீரரிடமோ பாதுகாவலரிடமோ கேளுங்கள். அமர்வு வெளியிடப்படுவதற்கு முன்பே தேர்வுகளும் வகுப்புகளும் மோதல்களாகத் தெரியும், பள்ளி வருகை ஒருங்கிணைப்புப் பணிகளை உருவாக்கும், முன்னேற்றம் அதன் மூலத்துடன் விளையாட்டு முன்னேற்றத்தின் அருகில் காட்டப்படும். அவர்கள் சம்மதிக்கும் வரை எதுவும் பகிரப்படாது.',
